```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::state_rw;

struct Node;

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        // Mark every considered item id as seen in the 'seen' store.
        // Count only ids not already recorded, so `recorded` is the number
        // of newly-seen items this run. `recorded` is a u32, so the
        // `recorded >= 0` postcondition holds by construction.
        let mut recorded: u32 = 0;
        for id in &published.considered {
            if state_rw::get(id).is_none() {
                state_rw::put(id, &published.date);
                recorded = recorded.saturating_add(1);
            }
        }

        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
```

